import assert from 'node:assert/strict';
import { distance } from '../src/core/math';
test('distance along an axis and at the same point', () => {
  assert.equal(distance({x:0,y:0},{x:3,y:0}),3);
  assert.equal(distance({x:2,y:2},{x:2,y:2}),0);
});

